<?php require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/widgets.php';require_role('admin');
$spec=all('SELECT e.nombre,COUNT(c.id) total FROM especialidades e LEFT JOIN medicos m ON m.especialidad_id=e.id LEFT JOIN citas c ON c.medico_id=m.id AND c.estado!="cancelada" GROUP BY e.id,e.nombre ORDER BY total DESC');
$med=all('SELECT u.nombre,u.apellido_paterno,COALESCE(e.nombre,"Sin especialidad") especialidad,COUNT(c.id) total FROM medicos m JOIN usuarios u ON u.id=m.usuario_id LEFT JOIN especialidades e ON e.id=m.especialidad_id LEFT JOIN citas c ON c.medico_id=m.id AND c.estado!="cancelada" GROUP BY m.id,u.nombre,u.apellido_paterno,e.nombre ORDER BY total DESC');
$monthly=all('SELECT DATE_FORMAT(fecha,"%Y-%m") mes,COUNT(*) total FROM citas WHERE fecha>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) AND estado!="cancelada" GROUP BY DATE_FORMAT(fecha,"%Y-%m") ORDER BY mes');
$maxS=max(1,...array_map(fn($x)=>(int)$x['total'],$spec));$maxM=max(1,...array_map(fn($x)=>(int)$x['total'],$med));
header_ui('Estadísticas');?><div class="page-intro"><h2>Indicadores de MiSalud 📊</h2><p>Estadísticas calculadas a partir de las citas registradas. Las citas canceladas no se cuentan como demanda.</p></div>
<div class="stat-grid"><?php stat_card('♡','Pacientes',count_rows('pacientes'));stat_card('✚','Médicos',count_rows('medicos'),'lavender');stat_card('▦','Citas registradas',count_rows('citas'),'peach');?></div>
<div class="dashboard-grid"><section class="panel"><h2>Especialidades más solicitadas</h2><?php foreach($spec as $r):?><div class="bar-row"><div><strong><?=e($r['nombre'])?></strong><small><?=(int)$r['total']?> citas</small></div><div class="bar-track"><span style="width:<?=100*(int)$r['total']/$maxS?>%"></span></div></div><?php endforeach;?></section>
<section class="panel"><h2>Médicos más solicitados</h2><?php foreach($med as $r):?><div class="bar-row"><div><strong><?=e($r['nombre'].' '.$r['apellido_paterno'])?></strong><small><?=e($r['especialidad'])?> · <?=(int)$r['total']?> citas</small></div><div class="bar-track"><span style="width:<?=100*(int)$r['total']/$maxM?>%"></span></div></div><?php endforeach;?></section></div>
<section class="panel"><h2>Tendencia mensual</h2><div class="table-wrap"><table><thead><tr><th>Mes</th><th>Citas no canceladas</th></tr></thead><tbody><?php foreach($monthly as $r):?><tr><td><?=e($r['mes'])?></td><td><?=(int)$r['total']?></td></tr><?php endforeach;?></tbody></table></div></section><?php footer_ui(); ?>
